// Writes tests/edit-vectors.json: the live editor's op rules as DATA, for a twin in another language (CONNECT's Python applier on the PC, NEXT-CONNECT 142).
// Each case is { name, state_before, op, refusal } or { name, state_before, op, state_after }: the refusal is the exact sentence the page shows; the state after is the whole
// state the page holds (clips in list order, look, duration, revision + 1). Generated by running assets/app-editor-core.js itself, so the twin is proved against the page's own rules.
//   node tools/make-edit-vectors.mjs            writes tests/edit-vectors.json
//   node tools/make-edit-vectors.mjs --check    exits 1 if the committed file differs (tests/edit-vectors.test.mjs does the same)
import fs from 'node:fs';
import vm from 'node:vm';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const window = {};
vm.runInNewContext(fs.readFileSync(path.join(root, 'assets/app-editor-core.js'), 'utf8'), { window, Error, Math, Number, Array, Object, String, JSON, Set, RegExp });
const E = window.ryagramEditor;
const plain = x => JSON.parse(JSON.stringify(x));

// ---- the states the cases start from (every one is built by newState, so what is stored is what the page would hold)
const comp = () => ({
  duration: 30,
  clips: [
    { id: 'v1', track: 'video', start: 0, len: 4, label: 'one', source: 'a.mp4', source_start: 2, min_len: 0.3, max_len: 10 },
    { id: 'v2', track: 'video', start: 4, len: 3, label: 'two', source: 'a.mp4', source_start: 3, min_len: 0.3, max_len: 5 },
    { id: 'v3', track: 'video', start: 7, len: 5, label: 'slide', picture: 'img-1', min_len: 0.5, max_len: 10 },
    { id: 'p1', track: 'pictures', start: 5, len: 2, label: 'chart', picture: 'img-2' },
    { id: 't1', track: 'text', start: 1, len: 3, label: 'Title', text: 'Housing', min_len: 0.5, max_len: 30 },
    { id: 'm1', track: 'music', start: 0, len: 30, label: 'music' }
  ]
});
const compLanes = () => ({ ...comp(), lanes: ['video', 'text'], limits: { text_chars: 20 } });
const data = () => ({ look: { 'network.color': '#6fd1bd', 'state.fill': '#23232d' } });
const STATES = { comp, comp_lanes: compLanes, data };

